mapper.select:
SELECT g.title AS value, g.goods_code AS goodsCode, g.id AS goods_id, g.category_id AS category_id, g.unit AS unit, g.pur_prc AS purPrc, g.sale_prc as salePrc, g.trade_prc as tradePrc, g.cost_price as costPrice, c.title AS categoryName, g.stock AS stock, g.title AS label FROM app_goods g LEFT JOIN app_goods_category c ON g.category_id = c.id LEFT JOIN app_supplier s ON g.supplier_id = s.id WHERE g.status = 1 and g.is_del = 0
AND COALESCE(g.stock, 0) <> 0
AND (
g.goods_code LIKE #{likeKey}
g.title LIKE #{likeKey}
OR g.py_code LIKE #{likePyCode}
OR s.name LIKE #{likeKey}
)
ORDER BY CASE WHEN g.py_code LIKE #{likePyCode} THEN 0 ELSE 1 END, g.title
LIMIT #{pageSize} OFFSET #{offset}

SELECT
g.*
FROM
app_goods g
LEFT JOIN app_goods_category c
ON g.category_id = c.id
LEFT JOIN app_supplier s
ON g.supplier_id = s.id
WHERE
g.status = 1
and g.is_del = 0

AND (
g.title LIKE #{likeKey}


    OR g.py_code LIKE #{likePyCode}

OR g.goods_code LIKE #{likeKey}
OR s.name LIKE #{likeKey}
)

    AND COALESCE(g.stock, 0) <> 0



    order by g.${query.column} ${query.order}
